test('latest complete WB roster keeps the same passage, releases absent players and handles registered departures',()=>{
 const seed={teams:[{id:'loud',name:'LOUD',aliases:['LOUD']}],people:[0,1,2,3].map(i=>({id:'p'+i,name:'Pessoa '+i,kind:i===3?'staff':'player',availability:'unknown',aliases:[],tenures:[{...tenure({status:'unverified',start:{date:'',edition:'WB 2025 S2',precision:'edition',certainty:'estimated'}}),id:'old'+i,teamName:'LOUD',order:1}]}))},entry={teamId:'loud',teamName:'LOUD',edition:'WB 2026 S2',role:'player',status:'active'},registration={version:'test-roster-v1',edition:'WB 2026 S2',legacyOverrideEdition:'WB 2026 S2',complete:true,previous:Object.fromEntries([0,1,2,3].map(i=>['p'+i,{...entry,edition:'WB 2026 S1'}])),entries:{p0:entry,p2:{...entry,left:true}}},s=setup(seed,registration);
 const kept=s.core.publicRead('person',{id:'p0'}).person;assert.equal(kept.current.length,1);assert.equal(kept.tenures.length,1);assert.equal(kept.current[0].id,'old0');assert.equal(kept.current[0].start.edition,'WB 2025 S2');assert.equal(kept.affiliationSource,'registration');assert.deepEqual(kept.teammates,[]);
 const absent=s.core.publicRead('person',{id:'p1'}).person;assert.equal(absent.availability,'free_agent');assert.equal(absent.current.length,0);assert.equal(absent.tenures[0].end.edition,'WB 2026 S1');assert.equal(absent.tenures[0].end.date,'');assert.equal(absent.freeAgentSince.edition,'WB 2026 S2');
 const left=s.core.publicRead('person',{id:'p2'}).person;assert.equal(left.availability,'free_agent');assert.equal(left.tenures[0].end.edition,'WB 2026 S2');assert.equal(s.core.publicRead('person',{id:'p3'}).person.availability,'unknown');
 const count=s.queries.length,again=C.create({sql:s.sql,transaction:s.transaction,seed,registration});again.publicRead('person',{id:'p0'});assert(!s.queries.slice(count).some(q=>q.startsWith('UPDATE career_people')));assert.equal(again.publicRead('person',{id:'p0'}).person.revision,kept.revision);
});
