test('market: the real migration preserves all 48 cards and names grouped in the sheet without altering careers',async()=>{const s=setup(),seed=require('../market-seed.json');assert.equal(seed.length,48);const real=new DatabaseSync(':memory:'),sql={exec(q,...a){let out=[];for(const part of q.split(';').filter(x=>x.trim())){const stmt=real.prepare(part);out=stmt.columns().length?stmt.all(...a):(stmt.run(...a),[]);}return out;}},transaction=fn=>{real.exec('BEGIN');try{const r=fn();real.exec('COMMIT');return r;}catch(e){real.exec('ROLLBACK');throw e;}};const core=C.create({sql,transaction,now:()=>Date.parse('2026-10-17T00:00Z')});const data=core.publicRead('market',{});assert.equal(data.total,48);assert.equal(data.entries[0].jogador,'wLiu');assert(data.entries.some(r=>r.jogador.includes('BRABOXX7')));const archived=(await core.admin(admin,{operation:'marketList'})).entries[0];await core.admin(admin,{operation:'marketSave',entry:{...archived,publication:'archived'},revision:1,nonce:nonce()});const reopened=C.create({sql,transaction});assert.equal(reopened.publicRead('market',{}).total,47);assert.equal(core.publicRead('person',{id:'cauan7'}).person.availability,'free_agent');});
