test('exporting existing exits previews only the selected teams latest free agents, publishes exactly once and never mutates careers',async()=>{const s=setup();const one=await edit(s,'saveTenure',{tenure:tenure()}),two=await edit(s,'saveTenure',{personId:'p1',tenure:tenure({role:'coach'})});for(const p of [one.person,two.person])await edit(s,'releasePerson',{personId:p.id,tenureIds:p.current.map(t=>t.id),departure:{date:'2026-10-14',certainty:'confirmed'},reason:'Organização pausou',source:'Anúncio SX TET'});let list=await s.core.admin(admin,{operation:'marketDepartureCandidates',teamName:'LOUD',limit:999});assert.equal(list.limit,20);assert.equal(list.total,2);assert(list.entries.every(p=>p.toName==='Sem equipe / F/A'));const before=list.entries.map(p=>JSON.stringify(s.core.publicRead('person',{id:p.personId}).person)),body={operation:'marketExportDepartures',teamId:list.team.id,publication:'published',nonce:nonce(),members:list.entries.map(p=>({personId:p.personId,tenureId:p.tenureId,revision:p.revision}))};const r=await s.core.admin(admin,body);assert.equal(r.exported.length,1);assert.equal(r.memberCount,2);assert.deepEqual(await s.core.admin(admin,body),r);const repeat=await s.core.admin(admin,{...body,nonce:nonce()});assert.equal(repeat.exported.length,0);assert.equal(repeat.skipped.length,2);assert.equal(s.core.publicRead('market',{}).total,1);assert.equal(s.core.publicRead('market',{}).entries[0].jogador,'Jogador 00, Jogador 01');list=await s.core.admin(admin,{operation:'marketDepartureCandidates',teamId:'loud'});assert(list.entries.every(p=>p.alreadyExported));assert.deepEqual(list.entries.map(p=>JSON.stringify(s.core.publicRead('person',{id:p.personId}).person)),before);assert(s.core.publicRead('market',{}).entries.every(e=>e.timeOrigem==='LOUD'&&e.timeDestino===''&&e.atualizacao==='14/10/2026'&&e.notes.includes('Organização pausou')));});
